use atlas_native_storage_contract::{create_workspace,add_file,file_revision,copy_file_from,undo_created,set_file_description};
use std::{fs,time::{SystemTime,UNIX_EPOCH}};
use rusqlite::Connection;
static SEQ:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);
fn root()->std::path::PathBuf{std::env::temp_dir().join(format!("atlas-copy-{}-{}-{}",std::process::id(),SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos(),SEQ.fetch_add(1,std::sync::atomic::Ordering::Relaxed)))}
fn path(p:&std::path::Path,id:&str)->String{Connection::open(p.join("atlas.sqlite3")).unwrap().query_row("SELECT path FROM objects WHERE id=?",[id],|r|r.get(0)).unwrap()}
#[test] fn copy_and_stale_refusal(){let a=root();let b=root();create_workspace(&a).unwrap();create_workspace(&b).unwrap();let id=add_file(&a,"copy.py",b"independent bytes").unwrap();set_file_description(&a,&id,"description").unwrap();let rev=file_revision(&a,&id).unwrap();let copy=copy_file_from(&b,&a,&id,&rev).unwrap();assert_ne!(copy,id);assert_eq!(fs::read(b.join(path(&b,&copy))).unwrap(),b"independent bytes");let desc:String=Connection::open(b.join("atlas.sqlite3")).unwrap().query_row("SELECT description FROM objects WHERE id=?",[&copy],|r|r.get(0)).unwrap();assert_eq!(desc,"description");set_file_description(&a,&id,"changed").unwrap();assert!(copy_file_from(&b,&a,&id,&rev).is_err());fs::remove_dir_all(a).unwrap();fs::remove_dir_all(b).unwrap();}
#[test] fn undo_rejects_stale(){let a=root();create_workspace(&a).unwrap();let id=add_file(&a,"copy.py",b"bytes").unwrap();let rev=file_revision(&a,&id).unwrap();set_file_description(&a,&id,"changed").unwrap();assert!(undo_created(&a,&id,&rev).is_err());assert!(a.join(path(&a,&id)).exists());fs::remove_dir_all(a).unwrap();}
#[test] fn copy_old_source_schema(){let a=root();let b=root();create_workspace(&a).unwrap();create_workspace(&b).unwrap();let id=add_file(&a,"old.txt",b"old schema bytes").unwrap();let rev=file_revision(&a,&id).unwrap();{let c=Connection::open(a.join("atlas.sqlite3")).unwrap();c.execute_batch("ALTER TABLE objects DROP COLUMN description").unwrap();}let copy=copy_file_from(&b,&a,&id,&rev).unwrap();assert_eq!(fs::read(b.join(path(&b,&copy))).unwrap(),b"old schema bytes");fs::remove_dir_all(a).unwrap();fs::remove_dir_all(b).unwrap();}
